const BUILTIN_PROVIDER_IDS = ['openai', 'anthropic', 'google', 'xai', 'github-copilot', 'gitlab'] as const

function isBuiltinProvider(providerId: string): providerId is (typeof BUILTIN_PROVIDER_IDS)[number] {
